    this.lastRefresh = null;
  }

  async getSecrets() {
    const now = Date.now();
    const shouldRefresh = !this.secrets || 
      (now - this.lastRefresh) > REFRESH_INTERVAL;

    if (shouldRefresh) {
      await this.refreshSecrets();
      this.lastRefresh = now;
