/**
 * Secrets Manager Abstraction Layer
 * 
 * Instead of loading secrets from .env files, use a proper secrets manager.
 * This module provides a unified interface for multiple backends.
 */

// Option 1: AWS Secrets Manager
const getSecretFromAWS = async (secretName) => {
  const { SecretsManager } = require('@aws-sdk/client-secrets-manager');

  const client = new SecretsManager({
    region: process.env.AWS_REGION || 'us-east-1'
  });

  try {
    const response = await client.getSecretValue({ SecretId: secretName });
    if (response.SecretString) {
      return JSON.parse(response.SecretString);
    }
    throw new Error(`Secret ${secretName} not found`);
  } catch (error) {
    console.error(`Failed to fetch secret ${secretName}:`, error.message);
    throw error;
  }
};

// Option 2: HashiCorp Vault
const getSecretFromVault = async (secretPath) => {
  const vault = require('node-vault')({
    endpoint: process.env.VAULT_ADDR,
    token: process.env.VAULT_TOKEN // This should come from a more secure source
  });

  try {
    const result = await vault.read(secretPath);
    return result.data;
  } catch (error) {
    console.error(`Failed to fetch secret from Vault: ${secretPath}`, error.message);
    throw error;
  }
};

// Option 3: Google Cloud Secret Manager
const getSecretFromGCP = async (secretName) => {
  const { SecretManagerServiceClient } = require('@google-cloud/secret-manager');
  const client = new SecretManagerServiceClient();

  const name = `projects/${process.env.GCP_PROJECT_ID}/secrets/${secretName}/versions/latest`;

  try {
    const [version] = await client.accessSecretVersion({ name });
    return version.payload.data.toString('utf8');
  } catch (error) {
    console.error(`Failed to fetch GCP secret ${secretName}:`, error.message);
    throw error;
  }
};

// Option 4: Azure Key Vault
const getSecretFromAzure = async (secretName) => {
  const { DefaultAzureCredential } = require('@azure/identity');
  const { SecretClient } = require('@azure/keyvault-secrets');

  const credential = new DefaultAzureCredential();
  const client = new SecretClient(process.env.AZURE_KEYVAULT_URL, credential);

  try {
    const secret = await client.getSecret(secretName);
    return secret.value;
  } catch (error) {
    console.error(`Failed to fetch Azure secret ${secretName}:`, error.message);
    throw error;
  }
};

/**
 * Unified secrets fetcher with caching
 */
class SecretsManager {
  constructor() {
    this.cache = new Map();
    this.provider = process.env.SECRETS_PROVIDER || 'aws';
  }

  async getSecret(key, options = {}) {
    const cacheKey = `${this.provider}:${key}`;

    // Check cache first
    if (this.cache.has(cacheKey) && !options.noCache) {
      return this.cache.get(cacheKey);
    }

    let value;

    switch (this.provider) {
      case 'aws':
        value = await getSecretFromAWS(key);
        break;
      case 'vault':
        value = await getSecretFromVault(key);
        break;
      case 'gcp':
        value = await getSecretFromGCP(key);
        break;
      case 'azure':
        value = await getSecretFromAzure(key);
        break;
      default:
        throw new Error(`Unknown secrets provider: ${this.provider}`);
    }

    // Cache with TTL (default 5 minutes)
    if (options.cacheTTL !== 0) {
      const ttl = options.cacheTTL || 300000;
      this.cache.set(cacheKey, value);
      setTimeout(() => this.cache.delete(cacheKey), ttl);
    }

    return value;
  }

  // Clear cache (useful for rotation)
  clearCache() {
    this.cache.clear();
  }
}

// Singleton instance
let instance = null;

const getSecretsManager = () => {
  if (!instance) {
    instance = new SecretsManager();
  }
  return instance;
};

module.exports = {
  SecretsManager,
  getSecretsManager,
  getSecretFromAWS,
  getSecretFromVault,
  getSecretFromGCP,
  getSecretFromAzure
};

/**
 * Secure Application Example
 * 
 * This version demonstrates proper secrets management and security best practices
 */

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { getSecretsManager } = require('./secrets-manager');

const app = express();

// ====================
// SECURITY MIDDLEWARE
// ====================

// Security headers
app.use(helmet());

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests, please try again later.' }
});
app.use(limiter);

// ====================
// SECRETS INITIALIZATION
// ====================

let dbConfig = null;
let stripeKey = null;

async function initializeSecrets() {
  const secretsManager = getSecretsManager();

  try {
    // Fetch secrets from the secrets manager, NOT from .env files
    const [dbSecret, stripeSecret] = await Promise.all([
      secretsManager.getSecret('production/database'),
      secretsManager.getSecret('production/stripe')
    ]);

    dbConfig = dbSecret;
    stripeKey = stripeSecret.api_key;

    console.log('✅ Secrets initialized successfully');
  } catch (error) {
    console.error('❌ Failed to initialize secrets:', error.message);
    process.exit(1);
  }
}

// ====================
// EXAMPLE: Secure Database Connection
// ====================

async function createDatabaseConnection() {
  const { Pool } = require('pg');

  // Use secrets from manager - NEVER from process.env for sensitive data
  const pool = new Pool({
    host: dbConfig.host,
    port: dbConfig.port,
    database: dbConfig.database,
    user: dbConfig.username,
    password: dbConfig.password,
    // SSL is REQUIRED for production
    ssl: {
      rejectUnauthorized: true,
      ca: dbConfig.ssl_cert // Even SSL certs should come from secrets manager
    }
  });

  return pool;
}

// ====================
// ROUTES
// ====================

app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    // NEVER include secrets in health checks or logs
    secrets_loaded: dbConfig !== null && stripeKey !== null
  });
});

app.get('/users', async (req, res) => {
  try {
    // Example using parameterized queries (prevents SQL injection)
    const pool = await createDatabaseConnection();
    const result = await pool.query(
      'SELECT id, name, email FROM users WHERE active = $1',
      [true] // Parameterized - SAFE from SQL injection
    );

    // Never expose internal IDs or sensitive fields
    const sanitizedUsers = result.rows.map(user => ({
      id: user.id,
      name: user.name,
      email: user.email
    }));

    res.json(sanitizedUsers);
  } catch (error) {
    // Never leak internal errors to clients
    console.error('Database error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// ====================
// ERROR HANDLING
// ====================

// Catch unhandled rejections - often caused by secrets issues
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // Exit and let process manager restart with fresh secrets
  process.exit(1);
});

// ====================
// STARTUP
// ====================

const PORT = process.env.PORT || 3000;

// Initialize secrets BEFORE starting server
initializeSecrets()
  .then(() => {
    app.listen(PORT, () => {
      console.log(`Server running on port ${PORT}`);
    });
  })
  .catch((error) => {
    console.error('Failed to start server:', error);
    process.exit(1);
  });

module.exports = app;

